namespace ghidra.app.util.viewer.field;





using ghidra.app.nav;
using ghidra.app.plugin.core.navigation.locationreferences;
using ghidra.app.services;
using ghidra.app.services;
using ghidra.app.util.query;
using ghidra.framework.plugintool;
using ghidra.program.model.listing;
using ghidra.program.model.symbol;
using ghidra.program.util;
using ghidra.util.table;
using ghidra.util.table.field;

/**
 * A handler to process {@link MnemonicFieldLocation} clicks.
 */
public class MnemonicFieldMouseHandler : FieldMouseHandlerExtension {

	private static Class<object>[] SUPPORTED_CLASSES = new Class[] { typeof(MnemonicFieldLocation) };

	/* @Override */
	public bool fieldElementClicked(object clickedObject, Navigatable sourceNavigatable,
			ProgramLocation location, MouseEvent mouseEvent, ServiceProvider serviceProvider) {

		if (mouseEvent.getClickCount() != 2 || mouseEvent.getButton() != MouseEvent.BUTTON1) {
			return false;
		}

		ProgramManager programManager = serviceProvider.getService(typeof(ProgramManager));
		if (programManager == null) {
			return false;
		}
		Program program = programManager.getCurrentProgram();
		Listing listing = program.getListing();
		CodeUnit codeUnit = listing.getCodeUnitAt(location.getAddress());
		return checkMemReferences(codeUnit, sourceNavigatable, serviceProvider);
	}

	private bool checkMemReferences(CodeUnit codeUnit, Navigatable navigatable,
			ServiceProvider serviceProvider) {

		if (codeUnit == null) {
			return false;
		}

		Reference[] refs = codeUnit.getMnemonicReferences();
		if (refs.length > 1) {
			List<OutgoingReferenceEndpoint> outgoingReferences = new();
			foreach (Reference reference in refs) {
				outgoingReferences.add(new OutgoingReferenceEndpoint(reference,
					ReferenceUtils.isOffcut(codeUnit.getProgram(), reference.getToAddress())));
			}

			IncomingReferencesTableModel model =
				new IncomingReferencesTableModel("Mnemonic", serviceProvider,
					codeUnit.getProgram(), outgoingReferences, null);

			TableService service = serviceProvider.getService(typeof(TableService));
			if (service != null) {
				service.showTable("Mnemonic References", "Mnemonic", model, "References",
					navigatable);
				return true;
			}
		}
		else if (refs.length == 1) {
			SymbolTable st = codeUnit.getProgram().getSymbolTable();
			Symbol symbol = st.getSymbol(refs[0]);

			ProgramLocation loc = null;
			if (symbol != null) {
				loc = symbol.getProgramLocation();
			}
			else {
				loc = new AddressFieldLocation(codeUnit.getProgram(), refs[0].getToAddress());
			}

			GoToService goToService = serviceProvider.getService(typeof(GoToService));
			if (goToService != null) {
				return goToService.goTo(navigatable, loc, navigatable.getProgram());
			}
		}

		return false;
	}

	/* @Override */
	public Class<object>[] getSupportedProgramLocations() {
		return SUPPORTED_CLASSES;
	}
}
